export const sourceSnapshot = snapshot;
const stop = new Set(
  "the a an and or to of in on is are does do how what where which show me his harsh project projects code implementation for with when from this that can you it he".split(
    " ",
  ),
);
export function terms(text) {
  return (
    String(text)
      .replace(/([a-z])([A-Z])/g, "$1 $2")
      .toLowerCase()
      .match(/[a-z0-9]{2,}/g)
      ?.filter((term) => !stop.has(term)) || []
  );
}
const chunks = snapshot.files.flatMap((file) => {
  const lines = file.text.split("\n");
  const result = [];
  for (let start = 0; start < lines.length;) {
    let end = Math.min(start + 32, lines.length);
    while (end > start + 1 && lines.slice(start, end).join("\n").length > 2600)
      end--;
    const text = lines.slice(start, end).join("\n");
    if (text.trim() && text.length <= 2600) {
      const id = createHash("sha256")
        .update(`${file.repo}/${file.path}@${file.commit}:${start + 1}:${end}`)
        .digest("hex")
        .slice(0, 16);
      result.push({
        id,
        repo: file.repo,
        slug: file.slug,
        title: file.title,
        path: file.path,
        commit: file.commit,
        startLine: start + 1,
        endLine: end,
        text,
        tokens: terms(text),
        heading: terms(`${file.title} ${file.path}`),
      });
    }
    if (end === lines.length) break;
    start += Math.max(1, end - start - 8);
  }
  return result;
});
const averageLength =
  chunks.reduce((n, c) => n + c.tokens.length, 0) / chunks.length;
const frequency = new Map();
for (const chunk of chunks)
  for (const term of new Set(chunk.tokens))
    frequency.set(term, (frequency.get(term) || 0) + 1);
const aliases = [
  [/\bugc\b|content studio/i, "ugc-platform"],
  [/\blendflow\b|lending|banking saas/i, "banking-saas"],
  [/banking agent|\bharness\b|transfer polic/i, "banking-agent-harness"],
  [/ticket|classifier|triage/i, "ai-support-ticket-classifier"],
  [
    /\brag\b|bm25|reciprocal|vector search/i,
    "hybrid-rag-documentation-assistant",
  ],
  [/\bportfolio\b|quota-lifecycle|quota reservation/i, "portfolio"],
];

// File intent supplements lexical ranking. An exported constructor can match a
// question well while omitting the Lua/dispatch code that actually enforces it.
const portfolioIntents = [
  {
    query: /voice|transcript|speech costs/i,
    path: /\/voice\.mjs$/,
    terms: "transcription speech usage accounting",
  },
  {
    query: /admission|concurren|rate.?limit/i,
    path: /\/admission\.mjs$/,
    terms: "atomic redis EVAL ADMIT_SCRIPT lease",
  },
];

export function retrievalQuery(messages) {
  if (typeof messages === "string") return messages;
  const users = messages.filter((message) => message.role === "user");
  const latest = users.at(-1)?.content || "";
  return terms(latest).length < 4
    ? `${users.at(-2)?.content || ""}\n${latest}`
    : latest;
}

export function retrieveCode(queryOrMessages, limit = 4) {
  const query = retrievalQuery(queryOrMessages);
  const selected = aliases.find(([pattern]) => pattern.test(query))?.[1];
  const intent =
    selected === "portfolio"
      ? portfolioIntents.find((item) => item.query.test(query))
      : undefined;
  const queryTerms = [...new Set(terms(query + " " + (intent?.terms || "")))];
  if (!queryTerms.length) return [];
  const ranked = chunks
    .filter((chunk) => !selected || chunk.slug === selected)
    .map((chunk) => {
      let score = intent?.path.test(chunk.path) ? 14 : 0;
      for (const term of queryTerms) {
        const tf = chunk.tokens.filter((token) => token === term).length;
        const df = frequency.get(term) || 0;
        if (tf)
          score +=
            (Math.log(1 + (chunks.length - df + 0.5) / (df + 0.5)) *
              (tf * 2.2)) /
            (tf + 1.2 * (0.25 + (0.75 * chunk.tokens.length) / averageLength));
        if (chunk.heading.includes(term)) score += 2;
      }
      return { chunk, score };
    })
    .filter((item) => item.score > 1)
    .sort((a, b) => b.score - a.score || a.chunk.id.localeCompare(b.chunk.id));
  const results = [];
  for (const { chunk } of ranked) {
    if (
      results.some(
        (other) =>
          other.repo === chunk.repo &&
          other.path === chunk.path &&
          Math.max(other.startLine, chunk.startLine) <=
            Math.min(other.endLine, chunk.endLine),
      )
    )
      continue;
    const { tokens: _tokens, heading: _heading, ...source } = chunk;
    results.push({
      ...source,
      href: `https://github.com/harshgavandit/${chunk.repo}/blob/${chunk.commit}/${chunk.path}#L${chunk.startLine}-L${chunk.endLine}`,
    });
    if (results.length >= Math.min(4, limit)) break;
  }
  return results;
}

export function codeEvidence(ids, queryOrMessages) {
  const retrieved = new Map(
    retrieveCode(queryOrMessages).map((chunk) => [chunk.id, chunk]),
  );
  return [...new Set(Array.isArray(ids) ? ids : [])]
    .flatMap((id) => (retrieved.has(id) ? [retrieved.get(id)] : []))
    .slice(0, 4);
}

export function publicCodeLinks(evidence) {
  return (Array.isArray(evidence) ? evidence : []).flatMap((item) => {
    const chunk = chunks.find((chunk) => chunk.id === item.id);
    if (!chunk) return [];
    return [
      {
        label: `${chunk.title} · ${chunk.path}:${chunk.startLine}–${chunk.endLine}`,
        href: `https://github.com/harshgavandit/${chunk.repo}/blob/${chunk.commit}/${chunk.path}#L${chunk.startLine}-L${chunk.endLine}`,
      },
    ];
  });
}

// Capability matching is a conservative guard, not a semantic truth oracle.
// Exact technologies are kept distinct: JavaScript cannot substantiate Java.
const catalogue = {
  react: /\breact(?:\.js)?\b/i,
  typescript: /\btypescript\b/i,
  javascript: /\bjavascript\b/i,
  python: /\bpython\b/i,
  node: /\bnode(?:\.js|js)?\b/i,
  express: /\bexpress(?:\.js)?\b/i,
  django: /\bdjango\b/i,
  fastapi: /\bfastapi\b/i,
  next: /\bnext(?:\.js|js)?\b/i,
  postgres: /\bpostgres(?:ql)?\b/i,
  sql: /\bsql\b|relational database/i,
  mongo: /\bmongo(?:db|ose)?\b/i,
  redis: /\bredis\b|\bupstash\b/i,
  docker: /\bdocker\b/i,
  kubernetes: /\bkubernetes\b|\bk8s\b/i,
  aws: /\baws\b|amazon web services/i,
  gcp: /\bgcp\b|google cloud/i,
  llm: /\bllms?\b|\bopenai\b|\bgemini\b|\blitellm\b|\bgenai\b|AI API|AI integration/i,
  rag: /\brag\b|retrieval.augmented/i,
  gemini: /\bgemini\b|google ai|google genai/i,
  openai: /\bopenai\b/i,
  prisma: /\bprisma\b/i,
  sequelize: /\bsequelize\b/i,
  jwt: /\bjwt\b/i,
  clerk: /\bclerk\b/i,
  rbac: /\brbac\b|role.based access/i,
  kafka: /\bkafka\b/i,
  java: /\bjava\b(?!script)/i,
  go: /\bgolang\b|\bgo\b(?= experience| development| services| programming|\s*$)/i,
  rust: /\brust\b/i,
  ruby: /\bruby\b|\brails\b/i,
  graphql: /\bgraphql\b/i,
  testing: /\btesting\b|\bpytest\b|\bvitest\b/i,
  cicd: /ci\s*\/\s*cd|github actions/i,
  k6: /\bk6\b/i,
  grafana: /\bgrafana\b/i,
  quotations: /\bquotations?\b|quotation.build/i,
  invoices: /\binvoic(?:e|ing)\b/i,
  email: /email.automation|automated email|email.sending/i,
};
export const capabilityKeys = (text) =>
  Object.entries(catalogue)
    .filter(([, pattern]) => pattern.test(String(text)))
    .map(([key]) => key);
export function supportedEvidence(row, sources) {
  const requested = capabilityKeys(row.requirement);
  const relevant = sources.filter(
    (source) =>
      requested.length &&
      requested.some((key) => source.capabilities.includes(key)),
  );
  const covered = new Set(relevant.flatMap((source) => source.capabilities));
  const missing = requested.filter((key) => !covered.has(key));
  if (!relevant.length || missing.length)
    return {
      assessment: "not_shown",
      evidence: [],
      explanation: missing.length
        ? `Published evidence does not establish ${missing.join(", ")} for this requirement.`
        : "The cited records do not establish this requirement. Please discuss the relevant experience directly with Harsh.",
    };
  const duration =
    /\b(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten)[+\s-]*years?\b/i.test(
      row.requirement,
    );
  const operational =
    /production|at scale|cluster|millions?|sla|slo|on.call/i.test(
      row.requirement,
    );
  const implementation = new Set(
    relevant
      .filter(
        (source) => source.kind === "employment" || source.kind === "project",
      )
      .flatMap((source) => source.implementationCapabilities || []),
  );
  const handsOn = requested.every((key) => implementation.has(key));
  const assessment =
    row.assessment === "not_shown"
      ? "not_shown"
      : duration || operational || !handsOn || row.assessment === "partial"
        ? "partial"
        : "supported";
  return {
    assessment,
    explanation: duration
      ? "Related technology is shown; the requested duration is not established by the cited records."
      : operational
        ? "Related implementation is shown; the requested production scale or operating responsibility needs direct verification."
        : !handsOn
          ? "The technology is listed, but the cited workflow does not establish hands-on use for every requested capability."
          : row.explanation,
    evidence: assessment === "not_shown" ? [] : relevant,
  };
}

export function factualContradictions(answer, query) {
  const text = String(answer).replace(/[’‘]/g, "'").toLowerCase();
  const findings = [];
  const claims = text
    .split(/[.!?;\n]/)
    .filter(
      (sentence) =>
        !/\b(?:not|never|cannot|can't|doesn't|isn't|no guarantee|without guaranteeing)\b/.test(
          sentence,
        ) && !/before.{0,40}(?:dispatch|provider)|pre.dispatch/.test(sentence),
    );
  if (
    /quota|reservation|abort|cancel/i.test(query) &&
    claims.some((sentence) =>
      /(?:always|every|guarantee[sd]?).{0,100}(?:refund|release|zero usage)|(?:refund|release).{0,100}(?:always|every dispatch)|provider usage is zero/.test(
        sentence,
      ),
    )
  ) {
    findings.push(
      "Unconditional post-dispatch refunds are not established by the quota implementation.",
    );
  }
  if (
    /ugc|content studio/i.test(query) &&
    claims.some((sentence) =>
      /(?:guarantee|100%|zero.loss|exactly.once).{0,80}(?:credit|refund|generation)|(?:atomic|transactional).{0,50}(?:provider request|credit refund)/.test(
        sentence,
      ),
    )
  ) {
    findings.push(
      "The UGC source does not establish atomic provider-and-credit transactions.",
    );
  }
  return findings;
}

import { createHash } from "node:crypto";
import { AI_PROMPT_VERSION, buildRequest } from "./openai.mjs";
import { codeEvidence, sourceSnapshot } from "./grounding.mjs";
import { factualContradictions } from "./evidence-policy.mjs";

const publicQuestions = new Set(
  [
    "Where does the portfolio release a quota reservation when a client aborts?",
    "How does UGC refund credits when generation fails?",
    "How does the banking agent harness require later-turn confirmation?",
    "How does the RAG project combine BM25 and vector search?",
  ].map((value) => value.toLowerCase()),
);
const normalizedQuestion = (messages) =>
  messages?.length === 1 && messages[0].role === "user"
    ? messages[0].content.trim().replace(/\s+/g, " ").toLowerCase()
    : "";
const ttl = 21600;
const namespace = "{portfolio-ai-operations:v1}";
const bounds = [250, 500, 1000, 2500, 5000, 10000, 30000, 60000];

export class PublicGuideCache {
  constructor({ store, clock = Date.now }) {
    this.store = store;
    this.clock = clock;
  }
  key(messages) {
    const question = normalizedQuestion(messages);
    if (!publicQuestions.has(question)) return null;
    return (
      namespace +
      ":cache:" +
      createHash("sha256")
        .update(
          AI_PROMPT_VERSION +
            sourceSnapshot.digest +
            JSON.stringify(buildRequest(messages)) +
            question,
        )
        .digest("hex")
    );
  }
  async get(messages) {
    const key = this.key(messages);
    if (!key || !this.store.configured || !this.store.command) return null;
    try {
      const raw = await this.store.command(["GET", key]);
      if (typeof raw !== "string" || raw.length > 26000) return null;
      const value = JSON.parse(raw);
      if (
        typeof value.answer !== "string" ||
        !value.answer.trim() ||
        value.answer.length > 4000 ||
        !Number.isFinite(value.createdAt) ||
        this.clock() - value.createdAt > ttl * 1000 ||
        value.createdAt > this.clock() ||
        value.version !== AI_PROMPT_VERSION ||
        value.snapshot !== sourceSnapshot.digest ||
        !Array.isArray(value.projectIds) ||
        !Array.isArray(value.sections) ||
        factualContradictions(value.answer, normalizedQuestion(messages)).length
      )
        return null;
      const evidence = codeEvidence(value.evidenceIds, messages);
      if (
        !Array.isArray(value.evidenceIds) ||
        value.evidenceIds.length > 4 ||
        !evidence.length ||
        evidence.length !== new Set(value.evidenceIds).size
      )
        return null;
      return {
        answer: value.answer,
        projectIds: value.projectIds,
        sections: value.sections,
        evidence,
        cacheCreatedAt: new Date(value.createdAt).toISOString(),
      };
    } catch {
      return null;
    } // Cache failure must not prevent the bounded live request.
  }
  async put(messages, result) {
    const key = this.key(messages);
    if (
      !key ||
      !this.store.configured ||
      !this.store.command ||
      !result.evidence?.length
    )
      return;
    const value = JSON.stringify({
      answer: result.answer,
      projectIds: result.projectIds,
      sections: result.sections,
      evidenceIds: result.evidence.map((item) => item.id),
      createdAt: this.clock(),
      version: AI_PROMPT_VERSION,
      snapshot: sourceSnapshot.digest,
    });
    if (value.length > 26000) return;
    try {
      await this.store.command(["SET", key, value, "EX", ttl]);
    } catch {
      /* A miss costs one admitted provider request; it never bypasses quota. */
    }
  }
}

export const RECORD_AI_METRIC = `
local key = KEYS[1]
redis.call('HINCRBY', key, 'total', 1)
redis.call('HINCRBY', key, ARGV[1], 1)
redis.call('HINCRBY', key, 'kind:' .. ARGV[2], 1)
redis.call('HINCRBY', key, 'cacheHits', ARGV[3])
redis.call('HINCRBY', key, 'inputTokens', ARGV[4])
redis.call('HINCRBY', key, 'outputTokens', ARGV[5])
redis.call('HINCRBY', key, 'allowanceMicros', ARGV[6])
redis.call('HINCRBY', key, 'providerCalls', ARGV[7])
if ARGV[7] == '1' then redis.call('HINCRBY', key, 'latency:' .. ARGV[8], 1) end
redis.call('HINCRBY', key, 'status:' .. ARGV[9], 1)
redis.call('EXPIRE', key, 2678400)
return 1
`;
export class AIMetrics {
  constructor({ store, clock = Date.now }) {
    this.store = store;
    this.clock = clock;
  }
  get configured() {
    return Boolean(this.store.configured && this.store.command);
  }
  async record(event) {
    if (!this.configured) return;
    const integer = (value) =>
      Number.isSafeInteger(value) && value >= 0 ? value : 0;
    const day = new Date(this.clock()).toISOString().slice(0, 10);
    const kind = ["guide", "voice", "recruiter", "triage"].includes(event.kind)
      ? event.kind
      : "guide";
    const status = [
      200, 400, 401, 403, 404, 405, 413, 415, 429, 499, 500, 502, 503, 504,
    ].includes(event.status)
      ? event.status
      : 500;
    const bucket = bounds.find((bound) => event.elapsedMs <= bound) || 60000;
    try {
      await this.store.command([
        "EVAL",
        RECORD_AI_METRIC,
        1,
        namespace + ":day:" + day,
        status === 200 ? "successes" : "failures",
        kind,
        event.cacheHit ? 1 : 0,
        integer(event.inputTokens),
        integer(event.outputTokens),
        integer(event.allowanceMicros),
        event.providerCall ? 1 : 0,
        bucket,
        status,
      ]);
    } catch {
      console.error(JSON.stringify({ event: "ai_metrics_unavailable" }));
    }
  }
  async snapshot() {
    if (!this.configured) return null;
    const days = Array.from({ length: 7 }, (_, i) =>
      new Date(this.clock() - i * 86400000).toISOString().slice(0, 10),
    );
    const fields = [
      "total",
      "successes",
      "failures",
      "cacheHits",
      "providerCalls",
      "inputTokens",
      "outputTokens",
      "allowanceMicros",
      ...bounds.map((value) => "latency:" + value),
      ...["guide", "voice", "recruiter", "triage"].map(
        (kind) => "kind:" + kind,
      ),
    ];
    const script = `local result = {} for _,key in ipairs(KEYS) do local row = redis.call('HMGET', key, unpack(ARGV)) for _,value in ipairs(row) do table.insert(result, value or '0') end end return result`;
    const raw = await this.store.command([
      "EVAL",
      script,
      days.length,
      ...days.map((day) => namespace + ":day:" + day),
      ...fields,
    ]);
    if (
      !Array.isArray(raw) ||
      raw.length !== days.length * fields.length ||
      raw.some(
        (value) =>
          !/^\d+$/.test(String(value)) || !Number.isSafeInteger(Number(value)),
      )
    )
      throw new Error("Invalid aggregate metrics");
    const totals = Object.fromEntries(fields.map((field) => [field, 0]));
    raw.forEach((value, i) => {
      totals[fields[i % fields.length]] += Number(value);
    });
    if (
      Object.values(totals).some((value) => !Number.isSafeInteger(value)) ||
      totals.total !== totals.successes + totals.failures ||
      totals.cacheHits > totals.total ||
      totals.providerCalls > totals.total
    )
      throw new Error("Inconsistent aggregate counters");
    const cutoff = Math.ceil(totals.providerCalls * 0.95);
    let cumulative = 0;
    const p95UpperMs = totals.providerCalls
      ? bounds.find((bound) => {
          cumulative += totals["latency:" + bound];
          return cumulative >= cutoff;
        }) || 60000
      : null;
    return {
      window: "7 UTC calendar days",
      from: days.at(-1),
      through: days[0],
      updatedAt: new Date(this.clock()).toISOString(),
      requests: totals.total,
      successes: totals.successes,
      failures: totals.failures,
      cacheHits: totals.cacheHits,
      providerCalls: totals.providerCalls,
      inputTokens: totals.inputTokens,
      outputTokens: totals.outputTokens,
      allowanceCostUsd: totals.allowanceMicros / 1000000,
      uncachedP95UpperMs: p95UpperMs,
      byTool: Object.fromEntries(
        ["guide", "voice", "recruiter", "triage"].map((kind) => [
          kind,
          totals["kind:" + kind],
        ]),
      ),
      note: "Anonymous aggregate counters only. Latency is a histogram upper bound for requests that dispatched providers, including failures. Collection began with this release; small samples are not an uptime guarantee.",
    };
  }
}

import {Request, Response } from 'express'
import * as Sentry from "@sentry/node";
import { prisma } from '../../config/database.js';
import {v2 as cloudinary } from 'cloudinary'
import {GenerateContentConfig, HarmBlockThreshold, HarmCategory} from '@google/genai'
import fs from 'fs';
import path from 'path';
import ai, { aiModels } from '../../config/ai.js';
import axios from 'axios';
import { toGenerationErrorResponse } from '../../lib/generationError.js';

const loadImage = (path: string, mimeType: string)=>{
    return {
        inlineData: {
            data: fs.readFileSync(path).toString('base64'),
            mimeType
        }
    }
}


export const createProject = async (req:Request, res: Response) => {
    let tempProjectId: string | undefined;
    const { userId } = req.auth();
    let isCreditDeducted = false;

    const {name = 'New Project', aspectRatio, userPrompt, productName, productDescription, targetLength = 5} = req.body;

    const images: any = req.files;

    if(images.length < 2 || !productName){
        return res.status(400).json({message: 'Please upload at least 2 images'})
    }

    const user = await prisma.user.findUnique({
        where: {id: userId}
    })

    if(!user){
        return res.status(409).json({message: 'Authenticated account is not initialized'})
    }

    if(user.credits < 5){
        return res.status(402).json({message: 'Insufficient credits'})
    }else{
        // deduct credits for image generation
        await prisma.user.update({
            where: {id: userId},
            data: {credits: {decrement: 5}}
        }).then(()=>{isCreditDeducted = true});
    }

    try {

        const uploadedImages = await Promise.all(
            images.map(async(item: any)=>{
                const result = await cloudinary.uploader.upload(item.path, {resource_type: 'image'});
                return result.secure_url
            })
        )

         const project = await prisma.project.create({
            data: {
                name,
                userId,
                productName,
                productDescription,
                userPrompt,
                aspectRatio,
                targetLength: parseInt(targetLength),
                uploadedImages,
                isGenerating: true
            }
         })

         tempProjectId = project.id;

         const model = aiModels.image;

         const generationConfig: GenerateContentConfig = {
            maxOutputTokens: 32768,
            temperature: 1,
            topP: 0.95,
            responseModalities: ['IMAGE'],
            imageConfig: {
                aspectRatio: aspectRatio || '9:16',
                imageSize: '1K'
            },
            safetySettings: [
                {
                    category: HarmCategory.HARM_CATEGORY_HATE_SPEECH,
                    threshold: HarmBlockThreshold.OFF,
                },
                {
                    category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT,
                    threshold: HarmBlockThreshold.OFF,
                },
                {
                    category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT,
                    threshold: HarmBlockThreshold.OFF,
                },
                {
                    category: HarmCategory.HARM_CATEGORY_HARASSMENT,
                    threshold: HarmBlockThreshold.OFF,
                },
            ]
         }

         // image to base64 structure for ai model
         const img1base64 = loadImage(images[0].path, images[0].mimetype);
         const img2base64 = loadImage(images[1].path, images[1].mimetype);

         const prompt = {
            text: `Combine the person and product into a realistic photo.
            Make the person naturally hold or use the product.
            Match lighting, shadows, scale and perspective.
            Make the person stand in professional studio lighting.
            Output ecommerce-quality photo realistic imagery.
            ${userPrompt}`
         }

         // Generate the image using the ai model
         const response: any = await ai.models.generateContent({
            model,
            contents: [img1base64, img2base64, prompt],
            config: generationConfig,
         })

         // Check if the response is valid
         if(!response?.candidates?.[0]?.content?.parts){
            throw new Error('Unexpected response')
         }

         const parts = response.candidates[0].content.parts;

         let finalBuffer: Buffer | null = null

         for(const part of parts){
            if(part.inlineData){
                finalBuffer = Buffer.from(part.inlineData.data, 'base64')
            }
         }

         if(!finalBuffer){
            throw new Error('Failed to generate image');
         }

         const base64Image = `data:image/png;base64,${finalBuffer.toString('base64')}`

         const uploadResult = await cloudinary.uploader.upload(base64Image, {resource_type: 'image'});

         await prisma.project.update({
            where: {id: project.id},
            data: {
                generatedImage: uploadResult.secure_url,
                isGenerating: false
            }
         })

         res.json({projectId: project.id})

    } catch (error: unknown) {
        const errorResponse = toGenerationErrorResponse(error);

        if(tempProjectId!){
            // update project status and error message
            await prisma.project.update({
                where: {id: tempProjectId},
                data: {isGenerating: false, error: errorResponse.message}
            })
        }

        if(isCreditDeducted){
            // add credits back
            await prisma.user.update({
                where: {id: userId},
                data: {credits: {increment: 5}}
            })
        }
        Sentry.captureException(error);
        res.status(errorResponse.status).json({ message: errorResponse.message });
    }
}


export const createVideo = async (req:Request, res: Response) => {
    const {userId} = req.auth()
    const { projectId } = req.body;
    let isCreditDeducted = false;

    const user = await prisma.user.findUnique({
        where: {id: userId}
    })

    if(!user){
        return res.status(409).json({message: 'Authenticated account is not initialized'})
    }

    if(user.credits < 10){
        return res.status(402).json({ message: 'Insufficient credits' });
    }

    // deduct credits for video generation
    await prisma.user.update({
        where: {id: userId},
        data: {credits: {decrement: 10}}
    }).then(()=>{ isCreditDeducted = true} );

    try {
        const project = await prisma.project.findUnique({
            where: {id: projectId, userId},
            include: {user: true}
        })

        if(!project || project.isGenerating){
            return res.status(404).json({ message: 'Generation in progress' });
        }

        if(project.generatedVideo){
            return res.status(404).json({ message: 'Video already generated' });
        }

        await prisma.project.update({
            where: {id: projectId},
            data: {isGenerating: true}
        })

        const prompt = `make the person showcase the product which is ${project.productName} ${project.productDescription && `and Product Description: ${project.productDescription}`}`

        const model = aiModels.video;

        if(!project.generatedImage){
            throw new Error('Generated image not found');
        }

        const image = await axios.get(project.generatedImage, {responseType: 'arraybuffer',})

        const imageBytes: any = Buffer.from(image.data)

        let operation: any = await ai.models.generateVideos({
            model,
            prompt,
            image: {
                imageBytes: imageBytes.toString('base64'),
                mimeType: 'image/png',
            },
            config: {
                aspectRatio: project?.aspectRatio || '9:16',
                numberOfVideos: 1,
                resolution: '720p',
            }
        })

        while (!operation.done){
            console.log('Waiting for video generation to complete...');
            await new Promise((resolve)=>setTimeout(resolve, 10000));
            operation = await ai.operations.getVideosOperation({
                operation: operation,
            })
        }

        const filename = `${userId}-${Date.now()}.mp4`;
        const filePath = path.join('videos', filename)

        // Create the images directory if it doesn't exist
        fs.mkdirSync('videos', {recursive: true})

        if(!operation.response.generatedVideos){
            throw new Error(operation.response.raiMediaFilteredReasons[0])
        }

        // Download the video.
        await ai.files.download({
            file: operation.response.generatedVideos[0].video,
            downloadPath: filePath,
        })

        const uploadResult = await cloudinary.uploader.upload(filePath, { resource_type: 'video' });

        await prisma.project.update({
            where: {id: project.id},
            data: {
                generatedVideo: uploadResult.secure_url,
                isGenerating: false
            }
        })

        // remove video file from disk after upload
        fs.unlinkSync(filePath);

        res.json({message: 'Video generation completed', videoUrl: uploadResult.secure_url})

    } catch (error:any) {

            // update project status and error message
            await prisma.project.update({
                where: {id: projectId, userId},
                data: {isGenerating: false, error: error.message}
            })

         if(isCreditDeducted){
            // add credits back
            await prisma.user.update({
                where: {id: userId},
                data: {credits: {increment: 10}}
            })
        }

        Sentry.captureException(error);
        res.status(500).json({ message: error.message });
    }
}

