"""Deterministic transfer validation.

The LLM may request any transfer it likes; whether it actually happens is
decided entirely here, in plain Python — never by the system prompt.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation

from app import mock_data


@dataclass
class TransferValidation:
    status: str  # "APPROVED" | "NEEDS_CLARIFICATION" | "REJECTED"
    beneficiary: dict[str, str] | None = None
    candidates: list[dict[str, str]] = field(default_factory=list)
    reason: str | None = None


def validate_transfer(beneficiary_query: str, amount: float) -> TransferValidation:
    try:
        money = Decimal(str(amount))
        if not money.is_finite() or money <= 0 or money != money.quantize(Decimal("0.01")):
            return TransferValidation(status="REJECTED", reason="Amount must be positive, finite, and have at most two decimal places.")
    except (InvalidOperation, ValueError):
        return TransferValidation(status="REJECTED", reason="Invalid transfer amount.")
    matches = mock_data.resolve_beneficiaries(beneficiary_query)

    if not matches:
        return TransferValidation(
            status="REJECTED", reason=f"No beneficiary matches '{beneficiary_query}'."
        )
    if len(matches) > 1:
        return TransferValidation(status="NEEDS_CLARIFICATION", candidates=matches)

    beneficiary = matches[0]

    if amount <= 0:
        return TransferValidation(
            status="REJECTED", reason="Transfer amount must be greater than zero."
        )

    account = mock_data.accounts[mock_data.ACCOUNT_ID]
    if account["status"] != "ACTIVE":
        return TransferValidation(status="REJECTED", reason="Your account is not active.")

    if beneficiary["status"] != "ACTIVE":
        return TransferValidation(
            status="REJECTED",
            reason=f"Beneficiary '{beneficiary['name']}' is blocked and cannot receive transfers.",
        )

    if money > Decimal(str(account["balance"])):
        return TransferValidation(status="REJECTED", reason="Insufficient account balance.")

    if Decimal(str(account["daily_used"])) + money > Decimal(str(account["daily_limit"])):
        remaining = account["daily_limit"] - account["daily_used"]
        return TransferValidation(
            status="REJECTED",
            reason=f"Daily transfer limit exceeded. Only {remaining} remains today.",
        )

    return TransferValidation(status="APPROVED", beneficiary=beneficiary)

"""
LLM response validation using Pydantic.

# PRODUCTION NOTE: In a real system, add custom business-rule validators
# (e.g., CRITICAL priority must always require_human_review), log validation
# failures to a monitoring system (Datadog, Sentry), and alert on high
# failure rates which could indicate a model degradation event.
"""

from dataclasses import dataclass, field
from typing import Any, Optional
from pydantic import ValidationError
import sys
import os

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from schema import TicketClassification


@dataclass
class ValidationResult:
    is_valid: bool
    validated_classification: Optional[TicketClassification] = None
    error_details: list[str] = field(default_factory=list)


def validate_classification(raw: Any) -> ValidationResult:
    """
    Validate LLM output against TicketClassification schema.
    Accepts a dict, a TicketClassification instance, or any JSON-serializable object.
    """
    errors: list[str] = []

    # Already a valid instance — re-validate to catch edge cases
    if isinstance(raw, TicketClassification):
        data = raw.model_dump()
    elif isinstance(raw, dict):
        data = raw
    else:
        return ValidationResult(
            is_valid=False,
            error_details=[f"Unexpected type: {type(raw).__name__}"],
        )

    # Pydantic structural validation
    try:
        classification = TicketClassification.model_validate(data)
    except ValidationError as e:
        for err in e.errors():
            errors.append(f"{'.'.join(str(x) for x in err['loc'])}: {err['msg']}")
        return ValidationResult(is_valid=False, error_details=errors)

    # Extra business-rule checks beyond Pydantic constraints
    if not (0.0 <= classification.confidence_score <= 1.0):
        errors.append(f"confidence_score {classification.confidence_score} out of range [0, 1]")

    if classification.confidence_score < 0.5 and not classification.requires_human_review:
        errors.append("Low confidence score should set requires_human_review=True")

    if errors:
        return ValidationResult(is_valid=False, error_details=errors)

    return ValidationResult(is_valid=True, validated_classification=classification)


